19	get_pdf	get_pdf_context	Read a PDF file and extract all text from it. Returns the full text content so you can answer questions about the document.	python_function	custom	{"function_name": "get_pdf_context", "code": "def get_pdf_context(pdf_path: str, max_chars: int = 50000) -> str:\\n    \\"\\"\\"Read a PDF file and extract text from it.\\n\\n    Args:\\n        pdf_path: Full path to the PDF file on disk\\n        max_chars: Maximum characters to return (default 50000, use -1 for all)\\n\\n    Returns:\\n        The text content of the PDF, truncated to max_chars.\\n    \\"\\"\\"\\n    import os\\n    from pypdf import PdfReader\\n    if not os.path.exists(pdf_path):\\n        return f\\"PDF file not found: {pdf_path}\\"\\n    try:\\n        reader = PdfReader(pdf_path)\\n        pages = []\\n        for i, page in enumerate(reader.pages, start=1):\\n            text = page.extract_text()\\n            if text and text.strip():\\n                pages.append(f\\"--- Page {i}/{len(reader.pages)} ---\\\\n{text.strip()}\\")\\n        if not pages:\\n            return f\\"No extractable text found in PDF ({len(reader.pages)} pages).\\"\\n        full_text = \\"\\\\n\\\\n\\".join(pages)\\n        if max_chars > 0 and len(full_text) > max_chars:\\n            return full_text[:max_chars]\\n        return full_text\\n    except Exception as e:\\n        return f\\"Failed to extract PDF text: {e}\\"\\n", "args_schema": {"pdf_path": {"type": "string", "description": "Full path to the PDF file on disk"}, "max_chars": {"type": "integer", "description": "Maximum characters to return (default 50000, use -1 for all)"}}}	{"type": "object", "properties": {"pdf_path": {"type": "string", "description": "Full path to the PDF file on disk"}, "max_chars": {"type": "integer", "description": "Maximum characters to return (default 50000, use -1 for all)"}}, "required": ["pdf_path"]}	string	null	t	t	\N	f	\N	24	2026-06-18 00:15:32.503095+08	1	2026-07-27 23:51:39.311548+08	1.0.0	\N		["pdf"]	2026-06-16 20:55:46.166591+08	2026-07-27 23:51:39.311714+08	f	\N
