45	ls	List Directory	List directory contents with metadata.\n\nShows files and directories with their types and sizes.\n\nArgs:\n    directory_path: Path to the directory (default: current directory)\n\nReturns:\n    Formatted list of directory contents with metadata\n\nExample:\n    >>> ls()\n    >>> ls("/home/user/projects")	python_function	custom	{"function_name": "ls", "code": "# --- imports ---\\n\\nfrom pathlib import Path\\n\\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\\n\\n# --- logger ---\\n\\nimport logging\\n\\nlogger = logging.getLogger(\\"langconfig.builtin_tool\\")\\n\\ndef ls(directory_path: str = \\".\\") -> str:\\n    \\"\\"\\"\\n    List directory contents with metadata.\\n\\n    Shows files and directories with their types and sizes.\\n\\n    Args:\\n        directory_path: Path to the directory (default: current directory)\\n\\n    Returns:\\n        Formatted list of directory contents with metadata\\n\\n    Example:\\n        >>> ls()\\n        >>> ls(\\"/home/user/projects\\")\\n    \\"\\"\\"\\n    try:\\n        path = Path(directory_path).resolve()\\n\\n        if not path.exists():\\n            return f\\"Error: Directory not found: {directory_path}\\"\\n\\n        if not path.is_dir():\\n            return f\\"Error: Path is not a directory: {directory_path}\\"\\n\\n        entries = list(path.iterdir())\\n\\n        if not entries:\\n            return f\\"Empty directory: {directory_path}\\"\\n\\n        # Format with metadata\\n        lines = []\\n        for entry in sorted(entries, key=lambda x: (not x.is_dir(), x.name.lower())):\\n            if entry.is_dir():\\n                lines.append(f\\"[DIR]  {entry.name}/\\")\\n            else:\\n                size = entry.stat().st_size\\n                if size < 1024:\\n                    size_str = f\\"{size}B\\"\\n                elif size < 1024 * 1024:\\n                    size_str = f\\"{size / 1024:.1f}KB\\"\\n                else:\\n                    size_str = f\\"{size / (1024 * 1024):.1f}MB\\"\\n                lines.append(f\\"[FILE] {entry.name} ({size_str})\\")\\n\\n        logger.info(f\\"Listed {len(entries)} entries in {directory_path}\\")\\n        return \\"\\\\n\\".join(lines)\\n\\n    except Exception as e:\\n        logger.error(f\\"Error listing directory {directory_path}: {e}\\")\\n        return f\\"Error listing directory: {str(e)}\\"", "args_schema": {"directory_path": {"type": "string", "description": "", "default": "."}}}	{"type": "object", "properties": {"directory_path": {"type": "string", "description": "", "default": "."}}, "required": []}	string	\N	t	t	builtin-seeder	f	\N	0	\N	0	\N	1.0.0	\N	filesystem	["builtin", "filesystem"]	2026-08-01 22:44:18.034563+08	2026-08-02 00:14:32.52354+08	t	\N
49	glob	Glob	Find files matching a glob pattern.\n\nSupports patterns like "**/*.py" (all Python files) or "src/*.ts" (TypeScript in src).\n\nArgs:\n    pattern: Glob pattern to match (e.g., "**/*.py", "*.md", "src/**/*.tsx")\n    path: Base directory to search from (default: current directory)\n\nReturns:\n    List of matching file paths\n\nExample:\n    >>> glob("**/*.py")\n    >>> glob("*.md", path="/docs")\n    >>> glob("src/**/*.tsx")	python_function	custom	{"function_name": "glob", "code": "# --- imports ---\\n\\nfrom pathlib import Path\\n\\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\\n\\n# --- logger ---\\n\\nimport logging\\n\\nlogger = logging.getLogger(\\"langconfig.builtin_tool\\")\\n\\ndef glob(pattern: str, path: str = \\".\\") -> str:\\n    \\"\\"\\"\\n    Find files matching a glob pattern.\\n\\n    Supports patterns like \\"**/*.py\\" (all Python files) or \\"src/*.ts\\" (TypeScript in src).\\n\\n    Args:\\n        pattern: Glob pattern to match (e.g., \\"**/*.py\\", \\"*.md\\", \\"src/**/*.tsx\\")\\n        path: Base directory to search from (default: current directory)\\n\\n    Returns:\\n        List of matching file paths\\n\\n    Example:\\n        >>> glob(\\"**/*.py\\")\\n        >>> glob(\\"*.md\\", path=\\"/docs\\")\\n        >>> glob(\\"src/**/*.tsx\\")\\n    \\"\\"\\"\\n    try:\\n        base_path = Path(path).resolve()\\n\\n        if not base_path.exists():\\n            return f\\"Error: Path not found: {path}\\"\\n\\n        matches = list(base_path.glob(pattern))\\n\\n        if not matches:\\n            return f\\"No files found matching pattern '{pattern}' in {path}\\"\\n\\n        # Format results with relative paths\\n        result_lines = []\\n        for match in sorted(matches):\\n            try:\\n                rel_path = match.relative_to(base_path)\\n                result_lines.append(str(rel_path))\\n            except ValueError:\\n                result_lines.append(str(match))\\n\\n        logger.info(f\\"Glob '{pattern}' found {len(matches)} files\\")\\n        return \\"\\\\n\\".join(result_lines)\\n\\n    except Exception as e:\\n        logger.error(f\\"Error with glob pattern {pattern}: {e}\\")\\n        return f\\"Error searching for files: {str(e)}\\"", "args_schema": {"pattern": {"type": "string", "description": ""}, "path": {"type": "string", "description": "", "default": "."}}}	{"type": "object", "properties": {"pattern": {"type": "string", "description": ""}, "path": {"type": "string", "description": "", "default": "."}}, "required": ["pattern"]}	string	\N	t	t	builtin-seeder	f	\N	0	\N	0	\N	1.0.0	\N	filesystem	["builtin", "filesystem"]	2026-08-01 22:44:18.034571+08	2026-08-02 00:14:32.523544+08	t	\N
50	grep	Grep	Search file contents for a regex pattern.\n\nSearches through files and returns matching lines with context.\n\nArgs:\n    pattern: Regular expression pattern to search for\n    path: File or directory to search (default: current directory)\n    file_pattern: Optional glob pattern to filter files (e.g., "*.py")\n\nReturns:\n    Matching lines with file paths and line numbers\n\nExample:\n    >>> grep("def main", path="src/")\n    >>> grep("TODO", file_pattern="*.py")\n    >>> grep("import.*requests", path=".", file_pattern="*.py")	python_function	custom	{"function_name": "grep", "code": "# --- imports ---\\n\\nfrom pathlib import Path\\n\\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\\n\\n# --- logger ---\\n\\nimport logging\\n\\nlogger = logging.getLogger(\\"langconfig.builtin_tool\\")\\n\\ndef grep(pattern: str, path: str = \\".\\", file_pattern: str = None) -> str:\\n    \\"\\"\\"\\n    Search file contents for a regex pattern.\\n\\n    Searches through files and returns matching lines with context.\\n\\n    Args:\\n        pattern: Regular expression pattern to search for\\n        path: File or directory to search (default: current directory)\\n        file_pattern: Optional glob pattern to filter files (e.g., \\"*.py\\")\\n\\n    Returns:\\n        Matching lines with file paths and line numbers\\n\\n    Example:\\n        >>> grep(\\"def main\\", path=\\"src/\\")\\n        >>> grep(\\"TODO\\", file_pattern=\\"*.py\\")\\n        >>> grep(\\"import.*requests\\", path=\\".\\", file_pattern=\\"*.py\\")\\n    \\"\\"\\"\\n    import re\\n\\n    try:\\n        base_path = Path(path).resolve()\\n\\n        if not base_path.exists():\\n            return f\\"Error: Path not found: {path}\\"\\n\\n        # Compile regex\\n        try:\\n            regex = re.compile(pattern, re.IGNORECASE)\\n        except re.error as e:\\n            return f\\"Error: Invalid regex pattern: {e}\\"\\n\\n        results = []\\n\\n        # Determine files to search\\n        if base_path.is_file():\\n            files_to_search = [base_path]\\n        else:\\n            glob_pattern = file_pattern or \\"**/*\\"\\n            files_to_search = [f for f in base_path.glob(glob_pattern) if f.is_file()]\\n\\n        # Search through files\\n        for file_path in files_to_search:\\n            try:\\n                content = file_path.read_text(encoding=\\"utf-8\\")\\n                lines = content.split('\\\\n')\\n\\n                for i, line in enumerate(lines, 1):\\n                    if regex.search(line):\\n                        try:\\n                            rel_path = file_path.relative_to(base_path)\\n                        except ValueError:\\n                            rel_path = file_path.name\\n                        results.append(f\\"{rel_path}:{i}: {line.strip()}\\")\\n\\n            except (UnicodeDecodeError, PermissionError):\\n                # Skip binary files or files we can't read\\n                continue\\n\\n        if not results:\\n            return f\\"No matches found for pattern '{pattern}'\\"\\n\\n        # Limit results to prevent huge outputs\\n        max_results = 100\\n        if len(results) > max_results:\\n            output = \\"\\\\n\\".join(results[:max_results])\\n            output += f\\"\\\\n\\\\n... and {len(results) - max_results} more matches\\"\\n        else:\\n            output = \\"\\\\n\\".join(results)\\n\\n        logger.info(f\\"Grep '{pattern}' found {len(results)} matches\\")\\n        return output\\n\\n    except Exception as e:\\n        logger.error(f\\"Error searching with pattern {pattern}: {e}\\")\\n        return f\\"Error searching: {str(e)}\\"", "args_schema": {"pattern": {"type": "string", "description": ""}, "path": {"type": "string", "description": "", "default": "."}, "file_pattern": {"type": "string", "description": "", "default": null}}}	{"type": "object", "properties": {"pattern": {"type": "string", "description": ""}, "path": {"type": "string", "description": "", "default": "."}, "file_pattern": {"type": "string", "description": "", "default": null}}, "required": ["pattern"]}	string	\N	t	t	builtin-seeder	f	\N	0	\N	0	\N	1.0.0	\N	filesystem	["builtin", "filesystem"]	2026-08-01 22:44:18.034573+08	2026-08-02 00:14:32.523545+08	t	\N
51	reasoning_chain	Reasoning Chain	Break down a complex task into logical reasoning steps.\n\nReplaces the MCP sequential-thinking server with native Python logic.\n\nArgs:\n    task: The task or problem to reason about\n    steps: Number of reasoning steps to perform (default: 5)\n\nReturns:\n    Structured reasoning breakdown\n\nExample:\n    >>> reasoning_chain("Plan a marketing strategy for a new product", 5)	python_function	custom	{"function_name": "reasoning_chain", "code": "# --- imports ---\\n\\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\\n\\n# --- logger ---\\n\\nimport logging\\n\\nlogger = logging.getLogger(\\"langconfig.builtin_tool\\")\\n\\ndef reasoning_chain(task: str, steps: int = 5) -> str:\\n    \\"\\"\\"\\n    Break down a complex task into logical reasoning steps.\\n\\n    Replaces the MCP sequential-thinking server with native Python logic.\\n\\n    Args:\\n        task: The task or problem to reason about\\n        steps: Number of reasoning steps to perform (default: 5)\\n\\n    Returns:\\n        Structured reasoning breakdown\\n\\n    Example:\\n        >>> reasoning_chain(\\"Plan a marketing strategy for a new product\\", 5)\\n    \\"\\"\\"\\n    logger.info(f\\"Reasoning chain for task: {task}\\")\\n\\n    # This is a simplified version. The actual LLM will do the reasoning.\\n    # This tool just provides a structure for the agent to follow.\\n\\n    reasoning_template = f\\"\\"\\"\\nTASK: {task}\\n\\nREASONING STEPS:\\n1. Analyze the requirements and constraints\\n2. Identify key objectives and success criteria\\n3. Consider potential approaches and trade-offs\\n4. Evaluate risks and mitigation strategies\\n5. Synthesize into a concrete action plan\\n\\nNote: This is a reasoning framework. The agent should fill in the actual analysis.\\n\\"\\"\\"\\n\\n    return reasoning_template\\n\\ndef task(\\n    description: str,\\n    subagent_type: str = \\"general\\",\\n    context: str = \\"\\",\\n    expected_output: str = \\"\\"\\n) -> str:\\n    \\"\\"\\"\\n    Delegate a task to a specialized subagent for execution.\\n\\n    Use this tool to spawn work to configured subagents. The subagent will\\n    execute the task and return the result. This enables parallel processing\\n    and specialization.\\n\\n    Args:\\n        description: Clear description of the task to perform\\n        subagent_type: Type of subagent to use (e.g., \\"research\\", \\"code\\", \\"writer\\", \\"general\\")\\n        context: Additional context or information for the subagent\\n        expected_output: Description of expected output format/content\\n\\n    Returns:\\n        Result from the subagent execution\\n\\n    Example:\\n        >>> task(\\n        ...     description=\\"Research the latest trends in AI image generation\\",\\n        ...     subagent_type=\\"research\\",\\n        ...     context=\\"Focus on diffusion models released in 2024\\",\\n        ...     expected_output=\\"A summary with key findings and links\\"\\n        ... )\\n    \\"\\"\\"\\n    logger.info(f\\"[TASK DELEGATION] Spawning subagent task: {description[:100]}...\\")\\n    logger.info(f\\"  subagent_type: {subagent_type}\\")\\n    logger.info(f\\"  context: {context[:100] if context else 'None'}...\\")\\n\\n    # This is a placeholder - actual subagent execution is handled by the DeepAgents framework\\n    # The framework intercepts this tool call and routes it to the appropriate subagent\\n    # based on the subagent configurations in the DeepAgentConfig\\n\\n    # For now, return a message indicating the tool was called\\n    # The actual implementation is in the DeepAgents middleware\\n    return f\\"\\"\\"[SUBAGENT TASK QUEUED]\\nTask: {description}\\nType: {subagent_type}\\nContext: {context if context else 'None'}\\nExpected Output: {expected_output if expected_output else 'Any relevant output'}\\n\\nNote: This task has been queued for subagent execution. The DeepAgents framework\\nwill route this to the appropriate configured subagent. If no subagents are\\nconfigured, this task will be executed by the main agent.\\"\\"\\"", "args_schema": {"task": {"type": "string", "description": ""}, "steps": {"type": "integer", "description": "", "default": 5}}}	{"type": "object", "properties": {"task": {"type": "string", "description": ""}, "steps": {"type": "integer", "description": "", "default": 5}}, "required": ["task"]}	string	\N	t	t	builtin-seeder	f	\N	0	\N	0	\N	1.0.0	\N	reasoning	["builtin", "reasoning"]	2026-08-01 22:44:18.034575+08	2026-08-02 00:14:32.523546+08	t	\N
52	task	Task (Subagent)	Delegate a task to a specialized subagent for execution.\n\nUse this tool to spawn work to configured subagents. The subagent will\nexecute the task and return the result. This enables parallel processing\nand specialization.\n\nArgs:\n    description: Clear description of the task to perform\n    subagent_type: Type of subagent to use (e.g., "research", "code", "writer", "general")\n    context: Additional context or information for the subagent\n    expected_output: Description of expected output format/content\n\nReturns:\n    Result from the subagent execution\n\nExample:\n    >>> task(\n    ...     description="Research the latest trends in AI image generation",\n    ...     subagent_type="research",\n    ...     context="Focus on diffusion models released in 2024",\n    ...     expected_output="A summary with key findings and links"\n    ... )	python_function	custom	{"function_name": "task", "code": "# --- imports ---\\n\\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\\n\\n# --- logger ---\\n\\nimport logging\\n\\nlogger = logging.getLogger(\\"langconfig.builtin_tool\\")\\n\\ndef task(\\n    description: str,\\n    subagent_type: str = \\"general\\",\\n    context: str = \\"\\",\\n    expected_output: str = \\"\\"\\n) -> str:\\n    \\"\\"\\"\\n    Delegate a task to a specialized subagent for execution.\\n\\n    Use this tool to spawn work to configured subagents. The subagent will\\n    execute the task and return the result. This enables parallel processing\\n    and specialization.\\n\\n    Args:\\n        description: Clear description of the task to perform\\n        subagent_type: Type of subagent to use (e.g., \\"research\\", \\"code\\", \\"writer\\", \\"general\\")\\n        context: Additional context or information for the subagent\\n        expected_output: Description of expected output format/content\\n\\n    Returns:\\n        Result from the subagent execution\\n\\n    Example:\\n        >>> task(\\n        ...     description=\\"Research the latest trends in AI image generation\\",\\n        ...     subagent_type=\\"research\\",\\n        ...     context=\\"Focus on diffusion models released in 2024\\",\\n        ...     expected_output=\\"A summary with key findings and links\\"\\n        ... )\\n    \\"\\"\\"\\n    logger.info(f\\"[TASK DELEGATION] Spawning subagent task: {description[:100]}...\\")\\n    logger.info(f\\"  subagent_type: {subagent_type}\\")\\n    logger.info(f\\"  context: {context[:100] if context else 'None'}...\\")\\n\\n    # This is a placeholder - actual subagent execution is handled by the DeepAgents framework\\n    # The framework intercepts this tool call and routes it to the appropriate subagent\\n    # based on the subagent configurations in the DeepAgentConfig\\n\\n    # For now, return a message indicating the tool was called\\n    # The actual implementation is in the DeepAgents middleware\\n    return f\\"\\"\\"[SUBAGENT TASK QUEUED]\\nTask: {description}\\nType: {subagent_type}\\nContext: {context if context else 'None'}\\nExpected Output: {expected_output if expected_output else 'Any relevant output'}\\n\\nNote: This task has been queued for subagent execution. The DeepAgents framework\\nwill route this to the appropriate configured subagent. If no subagents are\\nconfigured, this task will be executed by the main agent.\\"\\"\\"", "args_schema": {"description": {"type": "string", "description": ""}, "subagent_type": {"type": "string", "description": "", "default": "general"}, "context": {"type": "string", "description": "", "default": ""}, "expected_output": {"type": "string", "description": "", "default": ""}}}	{"type": "object", "properties": {"description": {"type": "string", "description": ""}, "subagent_type": {"type": "string", "description": "", "default": "general"}, "context": {"type": "string", "description": "", "default": ""}, "expected_output": {"type": "string", "description": "", "default": ""}}, "required": ["description"]}	string	\N	t	t	builtin-seeder	f	\N	0	\N	0	\N	1.0.0	\N	delegation	["builtin", "delegation"]	2026-08-01 22:44:18.034577+08	2026-08-02 00:14:32.523547+08	t	\N
53	doc_index_list	Doc Index - List Documents	List all indexed documents with metadata. Uses vectorless RAG (no embeddings, no chunking). Returns document names, types, and page counts.	python_function	custom	{"function_name": "doc_index_list", "code": "# --- imports ---\\n\\nfrom typing import Annotated, List, Literal, NotRequired, Optional, Dict, Any\\n\\nimport os\\n\\n_DOC_INDEX_BASE = None\\n\\ndef _get_doc_index_base() -> str:\\n    \\"\\"\\"Get the doc_index workspace base path.\\"\\"\\"\\n    global _DOC_INDEX_BASE\\n    if _DOC_INDEX_BASE is None:\\n        _DOC_INDEX_BASE = os.environ.get(\\n            \\"DOC_INDEX_BASE\\",\\n            os.path.join(os.path.dirname(os.path.dirname(__file__)), \\"outputs\\", \\"default\\")\\n        )\\n    return _DOC_INDEX_BASE\\n\\ndef _get_doc_client():\\n    \\"\\"\\"Get a DocIndexClient for the current workspace.\\"\\"\\"\\n    from services.doc_index_service import DocIndexClient\\n    return DocIndexClient(_get_doc_index_base())\\n\\ndef doc_index_list(workspace: Optional[str] = None) -> str:\\n    \\"\\"\\"\\n    List all indexed documents with metadata.\\n\\n    Uses GraphIndex-style vectorless retrieval \\u2014 no embeddings, no chunking.\\n    Returns document names, types, and page counts.\\n\\n    Args:\\n        workspace: Optional override for the doc_index workspace path\\n    \\"\\"\\"\\n    try:\\n        if workspace:\\n            from services.doc_index_service import DocIndexClient\\n            client = DocIndexClient(workspace)\\n        else:\\n            client = _get_doc_client()\\n\\n        docs = client.list_all()\\n        if not docs:\\n            return \\"No documents indexed yet.\\"\\n\\n        lines = [\\"## Indexed Documents\\", \\"\\"]\\n        for doc_id, meta in docs.items():\\n            lines.append(f\\"- **{meta.get('doc_name', 'Unknown')}** ({meta.get('type', '?')})\\")\\n            lines.append(f\\"  ID: `{doc_id}`\\")\\n            lines.append(f\\"  Pages: {meta.get('page_count', 0)}\\")\\n            lines.append(\\"\\")\\n        return \\"\\\\n\\".join(lines)\\n    except Exception as e:\\n        return f\\"Error listing documents: {e}\\"", "args_schema": {"workspace": {"type": "string", "description": "", "default": null}}}	{"type": "object", "properties": {"workspace": {"type": "string", "description": "", "default": null}}, "required": []}	string	\N	t	t	builtin-seeder	f	\N	0	\N	0	\N	1.0.0	\N	retrieval	["builtin", "retrieval"]	2026-08-01 22:44:18.034579+08	2026-08-02 00:14:32.523548+08	t	\N
54	doc_index_structure	Doc Index - Get Document Structure	Get the table-of-contents tree structure for a document (headings with page numbers, no body text). Use this to navigate before reading pages.	python_function	custom	{"function_name": "doc_index_structure", "code": "# --- imports ---\\n\\nfrom typing import Annotated, List, Literal, NotRequired, Optional, Dict, Any\\n\\nimport os\\n\\n_DOC_INDEX_BASE = None\\n\\ndef _get_doc_index_base() -> str:\\n    \\"\\"\\"Get the doc_index workspace base path.\\"\\"\\"\\n    global _DOC_INDEX_BASE\\n    if _DOC_INDEX_BASE is None:\\n        _DOC_INDEX_BASE = os.environ.get(\\n            \\"DOC_INDEX_BASE\\",\\n            os.path.join(os.path.dirname(os.path.dirname(__file__)), \\"outputs\\", \\"default\\")\\n        )\\n    return _DOC_INDEX_BASE\\n\\ndef _get_doc_client():\\n    \\"\\"\\"Get a DocIndexClient for the current workspace.\\"\\"\\"\\n    from services.doc_index_service import DocIndexClient\\n    return DocIndexClient(_get_doc_index_base())\\n\\ndef doc_index_structure(doc_id: str, workspace: Optional[str] = None) -> str:\\n    \\"\\"\\"\\n    Get the table-of-contents tree structure for a document.\\n\\n    Returns the document's heading hierarchy with page numbers (no body text).\\n    Use this to navigate to the right section before reading page content.\\n\\n    Args:\\n        doc_id: The document ID (from doc_index_list)\\n        workspace: Optional override for the doc_index workspace path\\n    \\"\\"\\"\\n    try:\\n        if workspace:\\n            from services.doc_index_service import DocIndexClient\\n            client = DocIndexClient(workspace)\\n        else:\\n            client = _get_doc_client()\\n\\n        doc_meta = client.get_document(doc_id)\\n        if \\"error\\" in doc_meta:\\n            return doc_meta[\\"error\\"]\\n\\n        structure = client.get_document_structure(doc_id)\\n        if not structure:\\n            return f\\"Document '{doc_meta.get('doc_name', doc_id)}' has no TOC structure. Use doc_index_pages to read content directly.\\"\\n\\n        def _format_tree(nodes, indent=0):\\n            lines = []\\n            for n in nodes:\\n                title = n.get(\\"title\\", \\"\\")\\n                page = n.get(\\"page\\", n.get(\\"line\\", \\"\\"))\\n                prefix = \\"  \\" * indent + \\"- \\"\\n                page_str = f\\" (p.{page})\\" if page else \\"\\"\\n                lines.append(f\\"{prefix}**{title}**{page_str}\\")\\n                children = n.get(\\"children\\", [])\\n                if children:\\n                    lines.extend(_format_tree(children, indent + 1))\\n            return lines\\n\\n        result = [f\\"## Structure: {doc_meta.get('doc_name', 'Document')}\\"]\\n        result.extend(_format_tree(structure))\\n        return \\"\\\\n\\".join(result)\\n\\n    except Exception as e:\\n        return f\\"Error getting document structure: {e}\\"", "args_schema": {"doc_id": {"type": "string", "description": ""}, "workspace": {"type": "string", "description": "", "default": null}}}	{"type": "object", "properties": {"doc_id": {"type": "string", "description": ""}, "workspace": {"type": "string", "description": "", "default": null}}, "required": ["doc_id"]}	string	\N	t	t	builtin-seeder	f	\N	0	\N	0	\N	1.0.0	\N	retrieval	["builtin", "retrieval"]	2026-08-01 22:44:18.034581+08	2026-08-02 00:14:32.523549+08	t	\N
55	doc_index_pages	Doc Index - Get Page Content	Get the full content of specific pages from a document. Specify pages as ranges like '5-7', specific pages like '3,8', or a single page like '12'.	python_function	custom	{"function_name": "doc_index_pages", "code": "# --- imports ---\\n\\nfrom typing import Annotated, List, Literal, NotRequired, Optional, Dict, Any\\n\\nimport os\\n\\n_DOC_INDEX_BASE = None\\n\\ndef _get_doc_index_base() -> str:\\n    \\"\\"\\"Get the doc_index workspace base path.\\"\\"\\"\\n    global _DOC_INDEX_BASE\\n    if _DOC_INDEX_BASE is None:\\n        _DOC_INDEX_BASE = os.environ.get(\\n            \\"DOC_INDEX_BASE\\",\\n            os.path.join(os.path.dirname(os.path.dirname(__file__)), \\"outputs\\", \\"default\\")\\n        )\\n    return _DOC_INDEX_BASE\\n\\ndef _get_doc_client():\\n    \\"\\"\\"Get a DocIndexClient for the current workspace.\\"\\"\\"\\n    from services.doc_index_service import DocIndexClient\\n    return DocIndexClient(_get_doc_index_base())\\n\\ndef doc_index_pages(doc_id: str, pages: str, workspace: Optional[str] = None) -> str:\\n    \\"\\"\\"\\n    Get the full content of specific pages from a document.\\n\\n    Args:\\n        doc_id: The document ID (from doc_index_list)\\n        pages: Page numbers to retrieve. Examples: '5-7' (range), '3,8' (specific), '12' (single).\\n               Use '1-3' to read the first few pages (often contains the table of contents).\\n        workspace: Optional override for the doc_index workspace path\\n    \\"\\"\\"\\n    try:\\n        if workspace:\\n            from services.doc_index_service import DocIndexClient\\n            client = DocIndexClient(workspace)\\n        else:\\n            client = _get_doc_client()\\n\\n        doc_meta = client.get_document(doc_id)\\n        if \\"error\\" in doc_meta:\\n            return doc_meta[\\"error\\"]\\n\\n        content_list = client.get_page_content(doc_id, pages)\\n        if not content_list:\\n            return f\\"No content found for pages: {pages}\\"\\n\\n        result = [f\\"## Content: {doc_meta.get('doc_name', 'Document')} (pages {pages})\\", \\"\\"]\\n        for entry in content_list:\\n            page_num = entry.get(\\"page\\", \\"?\\")\\n            text = entry.get(\\"content\\", \\"\\")\\n            result.append(f\\"--- Page {page_num} ---\\")\\n            result.append(text)\\n            result.append(\\"\\")\\n\\n        return \\"\\\\n\\".join(result)\\n    except Exception as e:\\n        return f\\"Error getting page content: {e}\\"", "args_schema": {"doc_id": {"type": "string", "description": ""}, "pages": {"type": "string", "description": ""}, "workspace": {"type": "string", "description": "", "default": null}}}	{"type": "object", "properties": {"doc_id": {"type": "string", "description": ""}, "pages": {"type": "string", "description": ""}, "workspace": {"type": "string", "description": "", "default": null}}, "required": ["doc_id", "pages"]}	string	\N	t	t	builtin-seeder	f	\N	0	\N	0	\N	1.0.0	\N	retrieval	["builtin", "retrieval"]	2026-08-01 22:44:18.034583+08	2026-08-02 00:14:32.52355+08	t	\N
